-- =====================================================================
-- SCRIPT SQL INSERT & UPDATE LENGKAP SURVEI RTKD BANYUWANGI (5 INSTRUMEN)
-- Memastikan seluruh tabel, kolom, master survei, dan 212 pertanyaan siap jalan
-- Waktu Pembuatan: 2026-10-23 08:03:57
-- =====================================================================

SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
START TRANSACTION;
SET time_zone = '+07:00';

-- ---------------------------------------------------------------------
-- 1. PASTIKAN STRUKTUR TABEL & KOLOM PENDUKUNG LENGKAP
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `survei_dinamis` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `KodeSurvei` varchar(100) NOT NULL,
  `Judul` varchar(255) NOT NULL,
  `Deskripsi` text DEFAULT NULL,
  `Lembaga` varchar(255) DEFAULT NULL,
  `Jenis` varchar(100) NOT NULL DEFAULT 'IKM',
  `Tahun` varchar(10) NOT NULL DEFAULT '2026',
  `Status` varchar(20) NOT NULL DEFAULT 'Aktif',
  `TipeSurvei` varchar(50) NOT NULL DEFAULT 'standar',
  `InstrumenList` varchar(255) NOT NULL DEFAULT 'A,B,C,D,E',
  `DaerahSurvei` varchar(255) DEFAULT NULL,
  `KodeWilayah` varchar(50) DEFAULT NULL,
  `BannerImage` varchar(255) DEFAULT NULL,
  `BannerColor` varchar(30) DEFAULT '#043168',
  `EstimasiWaktu` varchar(50) DEFAULT '5 - 15 Menit',
  `CreatedBy` varchar(100) DEFAULT NULL,
  `CreatedAt` datetime DEFAULT NULL,
  `UpdatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `KodeSurvei` (`KodeSurvei`),
  KEY `idx_kode_survei` (`KodeSurvei`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Penyesuaian kolom baru survei_dinamis
ALTER TABLE `survei_dinamis` ADD COLUMN IF NOT EXISTS `TipeSurvei` VARCHAR(50) NOT NULL DEFAULT 'standar' AFTER `Status`;
ALTER TABLE `survei_dinamis` ADD COLUMN IF NOT EXISTS `InstrumenList` VARCHAR(255) NOT NULL DEFAULT 'A,B,C,D,E' AFTER `TipeSurvei`;

CREATE TABLE IF NOT EXISTS `survei_pertanyaan` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `SurveiId` int(11) NOT NULL,
  `Instrumen` varchar(10) DEFAULT 'A',
  `Pertanyaan` text NOT NULL,
  `Deskripsi` text DEFAULT NULL,
  `Section` varchar(150) DEFAULT NULL,
  `Tipe` varchar(30) NOT NULL DEFAULT 'radio',
  `OpsiPilihan` longtext DEFAULT NULL,
  `IsRequired` tinyint(1) NOT NULL DEFAULT 1,
  `Urutan` int(11) NOT NULL DEFAULT 1,
  `ScaleMin` int(11) NOT NULL DEFAULT 1,
  `ScaleMax` int(11) NOT NULL DEFAULT 5,
  `ScaleMinLabel` varchar(100) DEFAULT 'Sangat Tidak Baik',
  `ScaleMaxLabel` varchar(100) DEFAULT 'Sangat Baik',
  `CreatedAt` datetime DEFAULT NULL,
  `UpdatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_survei_id` (`SurveiId`),
  KEY `idx_urutan` (`Urutan`),
  KEY `idx_instrumen` (`Instrumen`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Penyesuaian kolom baru survei_pertanyaan
ALTER TABLE `survei_pertanyaan` ADD COLUMN IF NOT EXISTS `Instrumen` VARCHAR(10) DEFAULT 'A' AFTER `SurveiId`;
ALTER TABLE `survei_pertanyaan` ADD COLUMN IF NOT EXISTS `Section` VARCHAR(150) NULL AFTER `Deskripsi`;

CREATE TABLE IF NOT EXISTS `survei_responden` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `SurveiId` int(11) NOT NULL,
  `Instrumen` varchar(10) DEFAULT 'A',
  `RespondenNama` varchar(150) DEFAULT 'Masyarakat',
  `RespondenNIK` varchar(25) DEFAULT NULL,
  `RespondenKontak` varchar(100) DEFAULT NULL,
  `RespondenGender` varchar(20) DEFAULT NULL,
  `RespondenUsia` varchar(20) DEFAULT NULL,
  `RespondenPendidikan` varchar(50) DEFAULT NULL,
  `RespondenPekerjaan` varchar(100) DEFAULT NULL,
  `Provinsi` varchar(100) DEFAULT NULL,
  `Kabupaten` varchar(100) DEFAULT NULL,
  `Kecamatan` varchar(100) DEFAULT NULL,
  `Desa` varchar(100) DEFAULT NULL,
  `AlamatDetail` text DEFAULT NULL,
  `Latitude` decimal(11,8) DEFAULT NULL,
  `Longitude` decimal(11,8) DEFAULT NULL,
  `LokasiAccuracy` decimal(8,2) DEFAULT NULL,
  `TotalSkor` decimal(10,2) NOT NULL DEFAULT 0.00,
  `RataRataSkor` decimal(10,2) NOT NULL DEFAULT 0.00,
  `MutuPelayanan` varchar(50) DEFAULT 'Baik',
  `IpAddress` varchar(45) DEFAULT NULL,
  `UserAgent` text DEFAULT NULL,
  `DevicePlatform` varchar(100) DEFAULT NULL,
  `CreatedBy` varchar(100) DEFAULT NULL,
  `CreatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_resp_survei_id` (`SurveiId`),
  KEY `idx_resp_instrumen` (`Instrumen`),
  KEY `idx_resp_created_at` (`CreatedAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Penyesuaian kolom baru survei_responden
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `Instrumen` VARCHAR(10) DEFAULT 'A' AFTER `SurveiId`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `RespondenNIK` VARCHAR(25) NULL DEFAULT NULL AFTER `RespondenNama`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `Latitude` DECIMAL(11,8) NULL DEFAULT NULL AFTER `AlamatDetail`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `Longitude` DECIMAL(11,8) NULL DEFAULT NULL AFTER `Latitude`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `LokasiAccuracy` DECIMAL(8,2) NULL DEFAULT NULL AFTER `Longitude`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `FotoDokumentasi` VARCHAR(255) NULL AFTER `LokasiAccuracy`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `DevicePlatform` VARCHAR(100) NULL DEFAULT NULL AFTER `UserAgent`;

CREATE TABLE IF NOT EXISTS `survei_jawaban` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `RespondenId` int(11) NOT NULL,
  `PertanyaanId` int(11) NOT NULL,
  `JawabanTeks` text DEFAULT NULL,
  `NilaiAngka` decimal(10,2) NOT NULL DEFAULT 0.00,
  `CreatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_jwb_responden_id` (`RespondenId`),
  KEY `idx_jwb_pertanyaan_id` (`PertanyaanId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 2. DATA UTAMA SURVEI RTKD BANYUWANGI (survei_dinamis Id = 4)
-- ---------------------------------------------------------------------

VALUES (4, 'survei-ketenagakerjaan-banyuwangi-rtkd-2026', 'Survei Ketenagakerjaan Banyuwangi (RTKD)', 'Survei Primer Ketenagakerjaan Kabupaten Banyuwangi dalam rangka Penyusunan Rencana Tenaga Kerja Daerah (RTKD) 2026. Mencakup 5 Instrumen: A (Perusahaan/Pemberi Kerja), B (Pencari Kerja & Lulusan), C (Pemangku Kepentingan/Narasumber), E (AHP Perbandingan Isu Strategis), dan D (Siswa Kelas 12 Sekolah Menengah).', 'Dinas Tenaga Kerja, Transmigrasi dan Perindustrian Kab. Banyuwangi', 'Ketenagakerjaan', '2026', 'Aktif', 'multi', 'A,B,C,D,E', 'Kabupaten Banyuwangi', '35.10', 'https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1200&q=80', '#043168', '15 - 25 Menit', 'Tim RTKD Banyuwangi', '2026-10-19 14:12:27', NOW());

-- ---------------------------------------------------------------------
-- 3. DAFTAR PERTANYAAN LENGKAP (212 BUTIR PERTANYAAN INSTRUMEN A, B, C, D, E)
-- ---------------------------------------------------------------------

DELETE FROM `survei_pertanyaan` WHERE `SurveiId` = 4;


-- ---------------------------------------------------------------------
-- 4. QUERY PEMERIKSAAN KESEHATAN SISTEM DATABASE
-- ---------------------------------------------------------------------

-- Periksa Status Survei Dinamis
SELECT `Id`, `KodeSurvei`, `Judul`, `TipeSurvei`, `InstrumenList`, `Status` FROM `survei_dinamis` WHERE `Id` = 4;

-- Periksa Jumlah Pertanyaan per Instrumen (Total harus 212 butir)
SELECT `Instrumen`, COUNT(*) AS `JumlahPertanyaan` FROM `survei_pertanyaan` WHERE `SurveiId` = 4 GROUP BY `Instrumen` ORDER BY `Instrumen`;

-- Periksa Jumlah Responden Masuk per Instrumen
SELECT `Instrumen`, COUNT(*) AS `JumlahResponden`, ROUND(AVG(`TotalSkor`), 2) AS `RataSkor` FROM `survei_responden` WHERE `SurveiId` = 4 GROUP BY `Instrumen` ORDER BY `Instrumen`;

COMMIT;
